import { defineTable } from "convex/server";
import { v } from "convex/values";

export const baseUnit = v.union(
  v.literal("Strip"),
  v.literal("Box"),
  v.literal("Bottle"),
  v.literal("Bag"),
);

export const drugsTable = defineTable({
  // User/file-provided identifier, never generated by the system
  drugId: v.string(),
  name: v.string(),
  brandName: v.string(),
  manufacturer: v.string(),
  // What individual pieces are called (tablets, capsules, ml...)
  pieceName: v.string(),
  // Drug picture, shared by every package form
  imageId: v.optional(v.id("_storage")),
  // Free text shown on drug cards; missing means blank
  specifications: v.optional(v.string()),
  remarks: v.optional(v.string()),
  // Denormalized text for the search index (Drug ID, names)
  searchText: v.string(),
  updatedAt: v.string(),
})
  .index("by_drugId", ["drugId"])
  .index("by_name", ["name"])
  .searchIndex("search_text", { searchField: "searchText" });

// One row per barcode. Each barcode has its own package form and stock amount.
export const drugPackagesTable = defineTable({
  drugRef: v.id("drugs"),
  // Empty string when the medicine has no barcode
  barcode: v.string(),
  // Normalized lookup key (GTIN-14 for numeric codes); empty when no barcode
  barcodeKey: v.string(),
  qtyPerUnit: v.number(),
  baseUnit: baseUnit,
  unitCount: v.number(),
  // Number of complete package forms on hand
  stock: v.number(),
  // Packaging pictures for this package form (e.g. blister); capped at MAX_PACKAGING_IMAGES
  imageIds: v.array(v.id("_storage")),
})
  .index("by_drug", ["drugRef"])
  .index("by_barcodeKey", ["barcodeKey"]);
